  const [a, l, extra] = c.trim().split('/');
  if (extra !== undefined) return null;
  const net = parseIp(a);
  if (!net || net.mapped) return null;
  const bits = net.v === 4 ? 32 : 128;
  const len = l === undefined ? bits : (/^\d{1,3}$/.test(l) ? Number(l) : NaN);
