function plan(input) {
  const cfg = input?.config?.response;
  const refuse = (code, reason) => ({ action: 'refuse', code, reason });
  if (!cfg || !input.config.wazuh_http) return refuse('invalid', 'lib-wazuh-active-response needs the lib-config output (with response and wazuh_http) as `config`');
  if (!['propose', 'execute'].includes(input.action)) return refuse('invalid', `unknown action ${input.action} (propose or execute)`);
  if (cfg.enabled !== true) return refuse('disabled', 'response actions are disabled (lib-config response.enabled, the kill switch)');
  if (!['dry_run', 'live'].includes(cfg.mode)) return refuse('config', `unknown lib-config response.mode ${cfg.mode} (dry_run or live)`);
  const cmd = cfg.commands?.[input.command];
  if (!cmd) return refuse('command', `${input.command} is not in the catalog (lib-config response.commands)`);
  if (!Number.isInteger(cmd.timeout_s) || cmd.timeout_s <= 0 || typeof cmd.api_command !== 'string' || cmd.api_command === '') {
    return refuse('config', `lib-config response.commands['${input.command}'] needs timeout_s and api_command`);
  }
  const ip = parseIp(input.srcip);
  if (!ip) return refuse('srcip', `no valid source address (${input.srcip ?? 'none given'})`);
  const cidrs = Array.isArray(cfg.protected_cidrs) ? cfg.protected_cidrs : [];
  const invalid = cidrs.filter((c) => !parseCidr(c));
  if (invalid.length > 0) return refuse('config', `lib-config response.protected_cidrs has invalid entries (${invalid.join(', ')}): nothing is proposed or sent until fixed`);
  const hit = cidrs.find((c) => inCidr(ip, c));
  if (hit) return refuse('protected', `${ip.text} is protected (lib-config response.protected_cidrs: ${hit})`);
  if (cfg.mode === 'live' && cidrs.filter((c) => !BUILTIN_PROTECTED.includes(c.trim())).length === 0) {
