  const halves = v.split('::');
  if (halves.length > 2) return null;
  const words = (h) => (h === '' ? [] : h.split(':'));
  const left = words(halves[0]);
  const right = halves.length === 2 ? words(halves[1]) : [];
  const last = halves.length === 2 ? right : left;
  if (last.length > 0 && last[last.length - 1].includes('.')) {
    const t = v4(last.pop());
    if (t === null) return null;
    last.push((t >> 16n).toString(16), (t & 0xffffn).toString(16));
  }
  if (![...left, ...right].every((w) => /^[0-9a-f]{1,4}$/.test(w))) return null;
  const fill = 8 - left.length - right.length;
  if (halves.length === 2 ? fill < 1 : fill !== 0) return null;
  const all = [...left, ...Array(halves.length === 2 ? fill : 0).fill('0'), ...right];
  const n = all.reduce((a, w) => (a << 16n) + BigInt(parseInt(w, 16)), 0n);
