function guard(p, cfg, calls, nowMs, sentMs) {
  const notSent = (reason) => ({ action: 'return', status: 'not_sent', code: 'lookup_failed', reason });
  const refused = (code, reason, agent = null) => ({ action: 'return', status: 'refused', code, reason, agent });
  if (!ok(calls.login)) return notSent(`Wazuh API login as n8n-response failed (${why(calls.login)})`);
  if (!ok(calls.list)) return notSent(`agent list as n8n-response failed (${why(calls.list)})`);
  const listed = agentList(calls.list);
  if (listed.error) return notSent(`agent list as n8n-response: ${listed.error}`);
  const wanted = p.agent.id ?? p.agent.name;
  const a = listed.items.find((x) => (p.agent.id ? x.id === p.agent.id : x.name === p.agent.name)) ?? null;
  if (!a || !(Array.isArray(a.group) && a.group.includes(cfg.agent_group))) {
    return refused('agent_not_in_group', `agent ${wanted} is not in group ${cfg.agent_group} (n8n-response doesn't list it there)`);
  }
  const agent = { id: a.id, name: a.name, status: a.status ?? null };
  if (a.status !== 'active') return refused('agent_not_active', `agent ${a.name} (${a.id}) is ${a.status ?? 'in an unknown state'}: a command sent now would be lost`, agent);
  if (p.protect_agent_ips) {
    if (!ok(calls.loginAll)) return notSent(`Wazuh API login as n8n-api failed (${why(calls.loginAll)}): agent addresses not checked`);
    if (!ok(calls.listAll)) return notSent(`agent list as n8n-api failed (${why(calls.listAll)}): agent addresses not checked`);
    const all = agentList(calls.listAll);
    if (all.error) return notSent(`agent list as n8n-api: ${all.error}: agent addresses not checked`);
