// pattern of N8N-6.2): only an error where the request never reached the API (refused, no route, name not resolved): a timeout or 5xx may have been run, so it is never repeated -> wait and call again; anything else
// is passed on. This node runs once per call, so $runIndex counts the calls.
// Never parks: the last failure goes into the result.
const r = $input.first().json;
const policy = $('Called by a workflow').first().json.config.wazuh_http;
const NODE = 'Send active response';
const attempt = $runIndex + 1;
const status = typeof r.statusCode === 'number' ? r.statusCode : null;
const thrown = r.error !== undefined && status === null; // HTTP node error output
const NETWORK = /ECONNREFUSED|ENOTFOUND|EAI_AGAIN|EHOSTUNREACH|ENETUNREACH/i;
const transient = thrown ? NETWORK.test(JSON.stringify(r)) : false;
const calls = policy.retry_waits_s.length + 1;
if (transient && attempt < calls) {
  return [{ json: { decision: 'retry', stage: NODE, attempt, wait_s: policy.retry_waits_s[attempt - 1],
    reason: thrown ? 'connection error or timeout' : `HTTP ${status}` } }];
}
if (thrown || transient) {
  const e = r.error;
  const detail = thrown
    ? (typeof e === 'string' ? e : [e?.message, e?.description].filter(Boolean).join(': ') || JSON.stringify(r))
    : `HTTP ${status}: ${typeof r.body === 'string' ? r.body : JSON.stringify(r.body)}`;
  return [{ json: { decision: 'error', stage: NODE, attempts: attempt, retry_exhausted: transient, http_status: status,
    timed_out: thrown && /timeout|timed out|ETIMEDOUT|ECONNABORTED|socket hang up|ECONNRESET/i.test(JSON.stringify(r)),
    message: `${detail}`.slice(0, 500) + (transient ? ` (${attempt} calls)` : '') } }];
}
return [{ json: { decision: 'response', stage: NODE, attempts: attempt, statusCode: status, body: r.body,
  date: r.headers?.date ?? null } }];

// lib-wazuh-active-response (C9 v0): what Wazuh did with the request. Success
// is not the HTTP status: Wazuh answers 200 with the agent in
// data.affected_items when it sent the command, and errors such as 1652
// (command not defined in the manager's ar.conf: no <active-response> block)
// come back inside a 200 in data.failed_items (A105). 200 means "sent to the
// agent", not "run". A timeout or 5xx is `unknown`: it may have been sent.
const FALLBACK = false;
function interpret(p, g, a, cfg) {
  const base = { agent: g.agent, request: g.request };
  if (a.decision === 'error') {
    if (a.timed_out) return { action: 'done', ...base, status: 'unknown', code: 'no_answer', reason: `no answer from the Wazuh API (${a.message}): the command may have been sent` };
    return { action: 'done', ...base, status: 'not_sent', code: 'unreachable', reason: `Wazuh API unreachable (${a.message})` };
  }
  const body = a.body !== null && typeof a.body === 'object' ? a.body : {};
  const d = body.data !== null && typeof body.data === 'object' ? body.data : {};
  const affected = Array.isArray(d.affected_items) ? d.affected_items.map(String) : [];
  const failed = (Array.isArray(d.failed_items) ? d.failed_items : []).map((f) => ({
    code: f?.error?.code ?? null, message: f?.error?.message ?? null, ids: Array.isArray(f?.id) ? f.id : [] }));
  const api = { http_status: a.statusCode, error: body.error ?? null, title: body.title ?? null,
    message: body.message ?? body.detail ?? null, total_affected: d.total_affected_items ?? affected.length, affected, failed };
  const date = a.date ? new Date(a.date) : null;
