  const first = failed[0];
  return { action: 'done', ...base, status: 'not_sent', code: 'refused_by_wazuh', api,
    reason: `not sent: Wazuh answered HTTP ${a.statusCode}${first ? `, error ${first.code}: ${first.message}` : (api.message ? `: ${api.message}` : '')}` };
}

const input = $('Called by a workflow').first().json;
const g = $('Guard').first().json;
const out = interpret($('Plan').first().json, g, $input.first().json, input.config.response);
