// lib-wazuh-active-response (C9 v0): the result, reached by exactly one path:
// refused by "Plan", returned by "Guard" (refused, not_sent, proposed,
// dry_run), or the send interpreted. `ok` is true for proposed, dry_run and
// sent. A live send is recorded in this workflow's static data for the rate
// cap (entries older than an hour dropped).
const HOUR_MS = 3600 * 1000;
function result(input, p, i, nowMs) {
  const cfg = input.config?.response ?? {};
  const status = i.action === 'refuse' ? 'refused' : i.status;
  const cmd = cfg.commands?.[input.command] ?? null;
  const sentCommand = i.request?.body?.command ?? null;
  const srcip = p.srcip ?? input.srcip ?? null;
  const agent = i.agent ?? null;
  let revert = null;
  if (status === 'sent' || status === 'unknown') {
    const tool = p.ip_version === 6 ? 'ip6tables' : 'iptables';
    revert = sentCommand === p.api_command
      ? { automatic: true, after_s: p.timeout_s,
        at: i.answered_at ? new Date(Date.parse(i.answered_at) + p.timeout_s * 1000).toISOString() : null }
      : { automatic: false, after_s: null, at: null,
        manual: `${tool} -D INPUT -s ${srcip} -j DROP; ${tool} -D FORWARD -s ${srcip} -j DROP` };
  }
  const on = agent ? `${agent.name} (agent ${agent.id})` : (input.agent?.name ?? input.agent?.id ?? 'unknown agent');
  let line;
  if (status === 'refused') line = `refused (${i.code}): ${i.reason}`;
  else if (status === 'proposed') line = `proposed: ${input.command} ${srcip} on ${on} for ${p.timeout_s} s (${p.mode})`;
  else if (status === 'dry_run') line = `dry_run: request built, not sent: ${i.request.method} ${i.request.path} ${JSON.stringify(i.request.body)}`;
  else if (status === 'sent') line = `sent to ${agent.name} (Wazuh accepted, total_affected ${i.api.total_affected}) at ${i.answered_at}`;
  else if (status === 'unknown') line = `unknown: ${i.reason}`;
  else line = `not sent: ${i.reason}`;
  return {
    ok: ['proposed', 'dry_run', 'sent'].includes(status),
    status, code: i.code ?? null, reason: i.reason ?? null, line,
    action: input.action ?? null, mode: cfg.mode ?? null, command: input.command ?? null,
    api_command: p.api_command ?? cmd?.api_command ?? null, sent_command: ['sent', 'unknown'].includes(status) ? sentCommand : null,
    timeout_s: p.timeout_s ?? cmd?.timeout_s ?? null, srcip, agent,
    request: i.request ?? null, api: i.api ?? null, first_api: i.first_api ?? null,
    answered_at: i.answered_at ?? null, answered_at_source: i.answered_at_source ?? null, revert,
  };
}

const input = $('Called by a workflow').first().json;
const out = result(input, $('Plan').first().json, $input.first().json, Date.now());
if (out.status === 'sent' || out.status === 'unknown') {
  const sd = $getWorkflowStaticData('global');
  const now = Date.now();
  sd.sent_ms = [...(Array.isArray(sd.sent_ms) ? sd.sent_ms : []).filter((t) => Number.isFinite(t) && now - t < HOUR_MS), now];
}
return [{ json: out }];
